export function getRelatedTreatmentLabel(
  treatmentId: string,
  locale: string,
): { name: string; desc: string } | null {
  const map = RELATED_TREATMENTS_L10N[locale as Locale] ?? {};
  return map[treatmentId] ?? null;
}
